{"kind":"tool","id":"bVXxYASj3W0","toolName":"write_file","input":{"path":"deploy/ubuntu/_verify_access_export.js","instructions":"One-off server-side verification that the live Access export returns real .mdb bytes","content":"/* One-off verification: hit the live API as an admin and inspect the Access export.
   Run on the server from /var/www/swimming-school/backend with NODE_ENV=production.
   Prints only status/content-type/size/signature — never credentials or tokens. */
process.env.NODE_ENV = process.env.NODE_ENV || "production";
const mongoose = require("mongoose");
const jwt = require("jsonwebtoken");
const { env } = require("./src/config/env");
const { User } = require("./src/modules/auth/user.model");

const BASE = "http://127.0.0.1:4000/api";

async function grab(path, token) {
  const res = await fetch(`${BASE}${path}`, {
    headers: token ? { Authorization: `Bearer ${token}` } : {},
  });
  const buf = Buffer.from(await res.arrayBuffer());
  return {
    status: res.status,
    type: res.headers.get("content-type") || "",
    disposition: res.headers.get("content-disposition") || "",
    len: buf.length,
    sig: buf.slice(4, 19).toString("latin1"),
    head: buf.slice(0, 2).toString("hex"),
  };
}

(async () => {
  await mongoose.connect(env.MONGODB_URI);
  const admin = await User.findOne({ role: "ADMIN", isActive: true }).select("_id").lean();
  if (!admin) {
    console.log("NO_ADMIN_FOUND");
    process.exit(1);
  }
  const token = jwt.sign(
    { sub: String(admin._id), role: "ADMIN", purpose: "access" },
    env.JWT_ACCESS_SECRET,
    { expiresIn: "5m" },
  );

  const unauth = await grab("/admin/reports/participants/export?format=access", null);
  console.log("unauth:", JSON.stringify(unauth));

  const mdb = await grab("/admin/reports/participants/export?format=access", token);
  console.log("reports-access:", JSON.stringify(mdb));

  const students = await grab("/enrollments/admin/participants/export?format=access", token);
  console.log("participants-access:", JSON.stringify(students));

  const excel = await grab("/admin/reports/participants/export", token);
  console.log("reports-excel:", JSON.stringify({ ...excel, sig: undefined }));

  const attendance = await grab("/admin/reports/attendance/export?format=access", token);
  console.log("attendance-access:", JSON.stringify(attendance));

  await mongoose.disconnect();
  process.exit(0);
})().catch(async (error) => {
  console.log("FAILED", error.message);
  try {
    await mongoose.disconnect();
  } catch {}
  process.exit(1);
});
